package nir.com.neonvegasslots;
import static org.junit.Assert.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=34)public class ButtonFeedbackTest{
 @Test public void downScalesAndDarkensWithoutChangingClick(){android.app.Activity a=Robolectric.buildActivity(android.app.Activity.class).setup().get();Button b=new Button(a);a.setContentView(b);b.layout(0,0,200,100);final int[] n={0};b.setOnClickListener(v->n[0]++);ButtonFeedback.install(b);b.dispatchTouchEvent(MotionEvent.obtain(0,0,0,50,50,0));assertEquals(.95f,b.getScaleX(),.001);assertEquals(.76f,b.getAlpha(),.001);b.dispatchTouchEvent(MotionEvent.obtain(0,10,1,50,50,0));org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(1,n[0]);assertEquals(1f,b.getAlpha(),.001);}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void pressedButtonPixels()throws Exception{
  android.app.Activity a=Robolectric.buildActivity(android.app.Activity.class).setup().get();android.widget.LinearLayout row=new android.widget.LinearLayout(a);a.setContentView(row);Button b=new Button(a);b.setText("Collect +300");b.setTextSize(20);row.addView(b,new android.widget.LinearLayout.LayoutParams(400,140));GameFonts.apply(row);row.measure(View.MeasureSpec.makeMeasureSpec(480,1073741824),View.MeasureSpec.makeMeasureSpec(220,1073741824));row.layout(0,0,480,220);b.dispatchTouchEvent(MotionEvent.obtain(0,0,0,50,50,0));android.graphics.Bitmap bm=android.graphics.Bitmap.createBitmap(480,220,android.graphics.Bitmap.Config.ARGB_8888);row.draw(new android.graphics.Canvas(bm));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-button-pressed.png")){bm.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}
 }
 @Test public void cancelNeverInvokesAction(){android.app.Activity a=Robolectric.buildActivity(android.app.Activity.class).setup().get();Button b=new Button(a);a.setContentView(b);b.layout(0,0,200,100);final int[] n={0};b.setOnClickListener(v->n[0]++);ButtonFeedback.install(b);b.dispatchTouchEvent(MotionEvent.obtain(0,0,0,50,50,0));b.dispatchTouchEvent(MotionEvent.obtain(0,10,3,50,50,0));assertEquals(0,n[0]);assertEquals(1,b.getAlpha(),.001);}
 @Test public void iconDownAndReleasePreserveLabel(){IconTile b=new IconTile(RuntimeEnvironment.getApplication(),"FREE COINS",1,2,3,4,"Watch an ad",30);b.setPressed(true);assertEquals(.95f,b.getScaleX(),.001);assertEquals("Watch an ad",b.getContentDescription());b.setPressed(false);assertFalse(b.isPressed());}
}
